"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";

export default function Home() {
  const [mode, setMode] = useState<"login" | "signup">("signup");
    const [email, setEmail] = useState("");
      const [password, setPassword] = useState("");
        const [user, setUser] = useState<any>(null);
          const [message, setMessage] = useState("");
            const [loading, setLoading] = useState(false);

              useEffect(() => {
                  supabase.auth.getSession().then(({ data }) => {
                        setUser(data.session?.user ?? null);
                            });

                                const { data } = supabase.auth.onAuthStateChange(
                                      (_event, session) => setUser(session?.user ?? null)
                                          );

                                              return () => data.subscription.unsubscribe();
                                                }, []);

                                                  async function handleAuth(e: React.FormEvent) {
                                                      e.preventDefault();
                                                          setLoading(true);
                                                              setMessage("");

                                                                  const result =
                                                                        mode === "signup"
                                                                                ? await supabase.auth.signUp({ email, password })
                                                                                        : await supabase.auth.signInWithPassword({ email, password });

                                                                                            if (result.error) {
                                                                                                  setMessage(result.error.message);
                                                                                                      } else if (mode === "signup" && !result.data.session) {
                                                                                                            setMessage("Account created! Check your email to confirm your account.");
                                                                                                                } else {
                                                                                                                      setMessage("Welcome to ConnectX!");
                                                                                                                            setUser(result.data.user);
                                                                                                                                }

                                                                                                                                    setLoading(false);
                                                                                                                                      }

                                                                                                                                        async function logout() {
                                                                                                                                            await supabase.auth.signOut();
                                                                                                                                                setUser(null);
                                                                                                                                                    setMessage("You have logged out.");
                                                                                                                                                      }

                                                                                                                                                        return (
                                                                                                                                                            <main style={styles.page}>
                                                                                                                                                                  <div style={styles.card}>
                                                                                                                                                                          <div style={styles.logo}>✦ ConnectX</div>
                                                                                                                                                                                  <p style={styles.subtitle}>Messages that bring us closer.</p>

                                                                                                                                                                                          {user ? (
                                                                                                                                                                                                    <>
                                                                                                                                                                                                                <h1>Welcome! 👋</h1>
                                                                                                                                                                                                                            <p style={styles.subtitle}>{user.email}</p>
                                                                                                                                                                                                                                        <button style={styles.button} onClick={logout}>
                                                                                                                                                                                                                                                      Log out
                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                            </>
                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                              <>
                                                                                                                                                                                                                                                                                                          <h1>{mode === "signup" ? "Create your space" : "Welcome back"}</h1>
                                                                                                                                                                                                                                                                                                                      <p style={styles.subtitle}>
                                                                                                                                                                                                                                                                                                                                    {mode === "signup"
                                                                                                                                                                                                                                                                                                                                                    ? "Join ConnectX and stay connected."
                                                                                                                                                                                                                                                                                                                                                                    : "Sign in to continue your conversations."}
                                                                                                                                                                                                                                                                                                                                                                                </p>

                                                                                                                                                                                                                                                                                                                                                                                            <form onSubmit={handleAuth}>
                                                                                                                                                                                                                                                                                                                                                                                                          <label style={styles.label}>Email address</label>
                                                                                                                                                                                                                                                                                                                                                                                                                        <input
                                                                                                                                                                                                                                                                                                                                                                                                                                        style={styles.input}
                                                                                                                                                                                                                                                                                                                                                                                                                                                        type="email"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="you@example.com"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onChange={(e) => setEmail(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label style={styles.label}>Password</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={styles.input}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="password"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder="Enter password (minimum 6 characters)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={password}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={(e) => setPassword(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  minLength={6}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button style={styles.button} disabled={loading}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {loading
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? "Please wait..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : mode === "signup"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ? "Create account →"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : "Sign in →"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </form>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p style={styles.switch}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {mode === "signup"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? "Already have an account?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : "New to ConnectX?"}{" "}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={styles.link}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onClick={() =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setMode(mode === "signup" ? "login" : "signup")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {mode === "signup" ? "Sign in" : "Create account"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {message && <p style={styles.message}>{message}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <footer>CONNECTX · BUILT FOR CONNECTION</footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

